package br.com.axecloud.app.feature.store
import androidx.lifecycle.*
import dagger.hilt.android.lifecycle.HiltViewModel
import kotlinx.coroutines.flow.*
import kotlinx.coroutines.launch
import javax.inject.Inject
@HiltViewModel class StoreViewModel @Inject constructor(private val repo:StoreRepository):ViewModel(){private val m=MutableStateFlow(StoreUiState());val state=m.asStateFlow();init{load()};fun load()=viewModelScope.launch{m.update{it.copy(loading=true,error=null)};runCatching{repo.load()}.onSuccess{p->m.update{it.copy(loading=false,isFilho=p.filho,products=p.products,orders=p.orders)}}.onFailure{e->m.update{it.copy(loading=false,error=e.message)}}};fun query(v:String)=m.update{it.copy(query=v)};fun category(v:String)=m.update{it.copy(category=v)};fun editor(p:StoreProduct?=null,open:Boolean=true)=m.update{it.copy(editor=p,editorOpen=open,error=null)};fun cart(open:Boolean)=m.update{it.copy(cartOpen=open)};fun consume()=m.update{it.copy(message=null)};fun add(p:StoreProduct)=m.update{val q=(it.cart[p.id]?:0);if(q>=p.stock)it.copy(message="Estoque disponível atingido.")else it.copy(cart=it.cart+(p.id to q+1),cartOpen=true)};fun quantity(p:StoreProduct,delta:Int)=m.update{val q=((it.cart[p.id]?:0)+delta).coerceIn(0,p.stock);it.copy(cart=if(q==0)it.cart-p.id else it.cart+(p.id to q))};fun save(f:ProductForm)=viewModelScope.launch{m.update{it.copy(saving=true,error=null)};runCatching{repo.save(f,m.value.editor?.id);repo.load()}.onSuccess{p->m.update{it.copy(saving=false,editorOpen=false,products=p.products,orders=p.orders,message="Produto salvo na vitrine.")}}.onFailure{e->m.update{it.copy(saving=false,error=e.message)}}};fun delete(p:StoreProduct)=viewModelScope.launch{m.update{it.copy(actionId=p.id)};runCatching{repo.delete(p)}.onSuccess{m.update{it.copy(actionId=null,products=it.products-p,cart=it.cart-p.id,message="Produto removido.")}}.onFailure{e->m.update{it.copy(actionId=null,error=e.message)}}};fun checkout(method:String)=viewModelScope.launch{m.update{it.copy(saving=true,error=null)};runCatching{repo.checkout(m.value.cart,m.value.products,method);repo.load()}.onSuccess{p->m.update{it.copy(saving=false,cart=emptyMap(),cartOpen=false,products=p.products,message="Pedido realizado com sucesso.")}}.onFailure{e->m.update{it.copy(saving=false,error=e.message)}}}}
